package api

func serviceDependentRotationSchemas() map[string]*Schema {
	str := func() *Schema { return &Schema{Type: "string"} }
	id := func() *Schema { return &Schema{Type: "string", Format: "uuid"} }
	stamp := func() *Schema { return &Schema{Type: "string", Format: "date-time"} }
	integer := func() *Schema { return &Schema{Type: "integer", Format: "int64"} }
	boolean := func() *Schema { return &Schema{Type: "boolean"} }
	array := func(item *Schema) *Schema { return &Schema{Type: "array", Items: item} }
	direction := func() *Schema { return &Schema{Type: "string", Enum: []string{"forward", "inverse"}} }
	return map[string]*Schema{
		"PAMDependentRef":                           object(map[string]*Schema{"agent_id": id(), "family": {Type: "string", Enum: []string{"services", "tasks", "iis"}}, "name": str()}, "agent_id", "family", "name"),
		"PAMDependentProbeBinding":                  object(map[string]*Schema{"ref": ref("PAMDependentRef"), "probe_id": str()}, "ref", "probe_id"),
		"PAMDependentRotationHost":                  object(map[string]*Schema{"binding": ref("PAMDependentHostBinding"), "inventory_run_id": id(), "inventory_digest": str(), "observed_at": stamp(), "dependents": array(ref("PAMDependentRef"))}, "binding", "inventory_run_id", "inventory_digest", "observed_at", "dependents"),
		"PAMDependentRotationPlan":                  object(map[string]*Schema{"version": integer(), "id": id(), "account": ref("PAMDependentAccountBinding"), "secret_name": str(), "hosts": array(ref("PAMDependentRotationHost")), "order": array(ref("PAMDependentRef")), "created_at": stamp(), "expires_at": stamp(), "digest": str()}, "version", "id", "account", "secret_name", "hosts", "order", "created_at", "expires_at", "digest"),
		"PAMServiceDependentRotationIntent":         object(map[string]*Schema{"plan": ref("PAMDependentRotationPlan"), "expected_version": integer(), "provider_binding": str(), "probes": array(ref("PAMDependentProbeBinding"))}, "plan", "expected_version", "provider_binding", "probes"),
		"PAMServiceDependentRotationPreviewRequest": object(map[string]*Schema{"secret_name": str(), "order": array(ref("PAMDependentRef")), "probes": array(ref("PAMDependentProbeBinding"))}, "secret_name", "order", "probes"),
		"PAMServiceDependentRotationPreview":        object(map[string]*Schema{"intent": ref("PAMServiceDependentRotationIntent"), "intent_digest": str()}, "intent", "intent_digest"),
		"PAMServiceDependentRotationRequest":        object(map[string]*Schema{"intent": ref("PAMServiceDependentRotationIntent"), "intent_digest": str(), "acknowledge_single_phase": boolean()}, "intent", "intent_digest", "acknowledge_single_phase"),
		"PAMServiceDependentRotation":               object(map[string]*Schema{"id": id(), "intent": ref("PAMServiceDependentRotationIntent"), "intent_digest": str(), "command_id": id(), "tenant_epoch": str(), "direction": direction(), "directory_restored": boolean(), "directory_apply_started": boolean(), "actor": str(), "failure": str(), "created_at": stamp(), "updated_at": stamp()}, "id", "intent", "intent_digest", "command_id", "tenant_epoch", "direction", "directory_restored", "directory_apply_started", "actor", "created_at", "updated_at"),
		"PAMServiceDependentRotationView":           object(map[string]*Schema{"rotation": ref("PAMServiceDependentRotation"), "command": ref("SecretStaticRotation")}, "rotation", "command"),
		"PAMDependentRotationStep":                  object(map[string]*Schema{"rotation_id": id(), "plan_digest": str(), "step_id": str(), "direction": direction(), "action": {Type: "string", Enum: []string{"preflight", "stop", "update", "start", "probe"}}, "ref": ref("PAMDependentRef"), "account_sid": str(), "probe_id": str(), "service": ref("PAMDependentNativeService"), "task": ref("PAMDependentNativeTask"), "pool": ref("PAMDependentNativePool"), "previous_pids": array(integer()), "challenge": id(), "not_before": stamp(), "deadline": stamp()}, "rotation_id", "plan_digest", "step_id", "direction", "action", "ref", "account_sid", "probe_id", "not_before", "deadline"),
		"PAMDependentRuntime":                       object(map[string]*Schema{"running": boolean(), "process_id": integer(), "account_sid": str()}, "running"),
		"PAMDependentTaskActionResult":              object(map[string]*Schema{"record_id": integer(), "result_code": integer()}, "record_id", "result_code"),
		"PAMDependentTaskRunProof":                  object(map[string]*Schema{"started_at": stamp(), "completed_at": stamp(), "path": str(), "account_sid": str(), "instance_id": id(), "start_record_id": integer(), "completion_record_id": integer(), "actions": array(ref("PAMDependentTaskActionResult"))}, "path", "account_sid", "instance_id", "start_record_id", "completion_record_id", "actions", "started_at", "completed_at"),
		"PAMDependentPoolRestartProof":              object(map[string]*Schema{"name": str(), "account_sid": str(), "config_sha256": str(), "was_started": boolean(), "stopped_observed": boolean(), "started_observed": boolean(), "previous_pids": {OneOf: []*Schema{array(integer()), {Type: "null"}}}}, "name", "account_sid", "config_sha256", "was_started", "stopped_observed", "started_observed", "previous_pids"),
		"PAMDependentFunctionalProof":               object(map[string]*Schema{"probe_id": str(), "challenge": id(), "process_id": integer(), "account_sid": str(), "task_instance_id": id(), "evidence_sha256": str()}, "probe_id", "challenge", "account_sid", "evidence_sha256"),
		"PAMDependentStepReport":                    object(map[string]*Schema{"rotation_id": id(), "plan_digest": str(), "step_id": str(), "direction": direction(), "status": {Type: "string", Enum: []string{"succeeded", "failed", "uncertain"}}, "failure": str(), "observed_at": stamp(), "runtime": ref("PAMDependentRuntime"), "task_proof": ref("PAMDependentTaskRunProof"), "pool_proof": ref("PAMDependentPoolRestartProof"), "functional": ref("PAMDependentFunctionalProof")}, "rotation_id", "plan_digest", "step_id", "direction", "status", "observed_at"),
		"PAMServiceDependentRotationStep":           object(map[string]*Schema{"intent": ref("PAMDependentRotationStep"), "status": {Type: "string", Enum: []string{"queued", "succeeded", "failed", "uncertain"}}, "delivery_status": str(), "outbox_id": integer(), "report": ref("PAMDependentStepReport"), "receipt_job_id": integer(), "attempt": integer(), "receipt_statement": str(), "receipt_signature_base64": str(), "signer_fingerprint": str(), "queued_at": stamp(), "received_at": stamp()}, "intent", "status", "queued_at"),
		"PAMServiceDependentRotationStepList":       object(map[string]*Schema{"items": array(ref("PAMServiceDependentRotationStep")), "next_cursor": str()}, "items"),
	}
}
